%% a01_b_Pickup_Remote_Properties.m
% Scans the H5OINA folder on the remote/network drive for the .mat files 
% generated by the Python script, and copies them to the local Masks directory.

clear; clc;

h5Dir = 'N:\EBSD-Analysis-2\Philipp_EBSD_analysis2\0009_Ti_cAxis_PTP_2\H5OINA';
angDir = 'C:\Users\phkr\OneDrive - empa.ch\MTEX_Data\Philipp\Ti_PTP\Ti_cAxis_PTP_2';
localMaskDir = fullfile(angDir, 'Masks');

if ~exist(localMaskDir, 'dir')
    mkdir(localMaskDir);
end

fprintf('Scanning %s for remote properties...\n', h5Dir);
matFiles = dir(fullfile(h5Dir, '**', '*_h5oina_props.mat'));

if isempty(matFiles)
    warning('No _h5oina_props.mat files found in %s!\nMake sure you ran the Python script on the remote PC.', h5Dir);
    return;
end

for i = 1:length(matFiles)
    source = fullfile(matFiles(i).folder, matFiles(i).name);
    
    % The python script saves files with the .h5oina basename.
    baseNameH5 = matFiles(i).name(1:end-17); % remove '_h5oina_props.mat'
    
    % Find corresponding .ang file
    angFiles = dir(fullfile(angDir, '**', [baseNameH5, '*.ang']));
    if isempty(angFiles)
        warning('Found remote MAT %s but no matching .ang file locally. Skipping.', matFiles(i).name);
        continue;
    end
    
    angBaseName = angFiles(1).name(1:end-4);
    dest = fullfile(localMaskDir, sprintf('%s_h5oina_props.mat', angBaseName));
    
    if exist(dest, 'file')
        fprintf('File %s already exists locally. Skipping...\n', dest);
    else
        fprintf('Copying %s\n  -> %s\n', matFiles(i).name, dest);
        copyfile(source, dest);
    end
end

fprintf('All remote properties synced! You can now run a02 or a03.\n');
